-- Guards: Provider Description actual source/provider/eligible-course index paths.
CREATE UNIQUE INDEX IF NOT EXISTS evidence_artifacts_pkey ON pipeline.evidence_artifacts USING btree (id);
CREATE INDEX IF NOT EXISTS evidence_entity_idx ON pipeline.evidence_artifacts USING btree (entity_id, captured_at DESC);
CREATE INDEX IF NOT EXISTS evidence_source_idx ON pipeline.evidence_artifacts USING btree (source_id);
CREATE INDEX IF NOT EXISTS evidence_supersedes_idx ON pipeline.evidence_artifacts USING btree (supersedes_evidence_id);
CREATE INDEX IF NOT EXISTS pipeline_evidence_job_idx ON pipeline.evidence_artifacts USING btree (job_id) WHERE (job_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS evidence_artifacts_captured_idx ON pipeline.evidence_artifacts USING btree (captured_at DESC, id);
CREATE INDEX IF NOT EXISTS evidence_artifacts_type_captured_idx ON pipeline.evidence_artifacts USING btree (evidence_type, captured_at DESC);
CREATE INDEX IF NOT EXISTS evidence_artifacts_mime_captured_idx ON pipeline.evidence_artifacts USING btree (mime_type, captured_at DESC);
CREATE INDEX IF NOT EXISTS layer2_evidence_group_version_idx ON pipeline.evidence_artifacts USING btree (evidence_group_key, capture_version DESC) WHERE (evidence_group_key IS NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS layer2_evidence_group_capture_version_uq ON pipeline.evidence_artifacts USING btree (evidence_group_key, capture_version) WHERE ((evidence_group_key IS NOT NULL) AND (capture_version IS NOT NULL));
CREATE UNIQUE INDEX IF NOT EXISTS evidence_standard_group_hash_uq ON pipeline.evidence_artifacts USING btree (evidence_group_key, content_hash) WHERE ((retention_class = 'standard_365'::text) AND (evidence_group_key IS NOT NULL) AND (content_hash IS NOT NULL));
CREATE INDEX IF NOT EXISTS evidence_artifacts_source_hash_idx ON pipeline.evidence_artifacts USING btree (source_id, content_hash);
CREATE INDEX IF NOT EXISTS pipeline_evidence_activity_time_idx ON pipeline.evidence_artifacts USING btree (COALESCE(captured_at, created_at) DESC, id);
CREATE INDEX IF NOT EXISTS evidence_metadata_layer_captured_idx ON pipeline.evidence_artifacts USING btree (COALESCE((metadata ->> 'layer'::text), ''::text), captured_at DESC);
CREATE INDEX IF NOT EXISTS evidence_artifacts_storage_path_idx ON pipeline.evidence_artifacts USING btree (storage_path);
CREATE INDEX IF NOT EXISTS evidence_artifacts_captured_nulls_last_idx ON pipeline.evidence_artifacts USING btree (captured_at DESC NULLS LAST, id);
CREATE INDEX IF NOT EXISTS evidence_artifacts_created_at_idx ON pipeline.evidence_artifacts USING btree (created_at DESC);
CREATE INDEX IF NOT EXISTS evidence_artifacts_layer2_overview_coalesce_idx ON pipeline.evidence_artifacts USING btree (review_state, retention_class, captured_at DESC) WHERE (COALESCE((metadata ->> 'layer'::text), ''::text) = '2'::text);
CREATE INDEX IF NOT EXISTS evidence_artifacts_source_url_pattern_idx ON pipeline.evidence_artifacts USING btree (lower(source_url) text_pattern_ops);
CREATE UNIQUE INDEX IF NOT EXISTS sources_pkey ON pipeline.sources USING btree (id);
CREATE INDEX IF NOT EXISTS pipeline_sources_provider_idx ON pipeline.sources USING btree (provider_id, status);
CREATE INDEX IF NOT EXISTS sources_country_idx ON pipeline.sources USING btree (country_id);
CREATE INDEX IF NOT EXISTS sources_system_idx ON pipeline.sources USING btree (system_id);
CREATE UNIQUE INDEX IF NOT EXISTS pipeline_sources_scholarship_source_key_uidx ON pipeline.sources USING btree (((metadata ->> 'scholarship_source_key'::text))) WHERE (metadata ? 'scholarship_source_key'::text);
CREATE UNIQUE INDEX IF NOT EXISTS providers_pkey ON catalogue.providers USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS providers_stable_key_key ON catalogue.providers USING btree (stable_key);
CREATE INDEX IF NOT EXISTS providers_country_pub_idx ON catalogue.providers USING btree (country_id, publication_status);
CREATE INDEX IF NOT EXISTS providers_type_idx ON catalogue.providers USING btree (provider_type_id);
CREATE INDEX IF NOT EXISTS providers_subdivision_idx ON catalogue.providers USING btree (subdivision_id);
CREATE UNIQUE INDEX IF NOT EXISTS courses_pkey ON catalogue.courses USING btree (id);
CREATE INDEX IF NOT EXISTS courses_provider_code_trim_active_idx ON catalogue.courses USING btree (provider_id, upper(btrim(course_code))) WHERE (lifecycle_status = 'active'::text);
